import java.net.*;
import java.net.http.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.util.stream.Collectors;

public class App {
  public static void main(String[] args) throws Exception {
    var httpClient = HttpClient.newBuilder().build();

    HashMap<String, String> params = new HashMap<>();
    params.put("format", "JSON");
    params.put("id", "REPLACE-WITH-YOUR-LICENSE-KEY");
    params.put("a1", "22382 Avenida Empresa");
    params.put("admarea", "CA");
    params.put("ctry", "USA");
    params.put("loc", "Rancho Santa Margarita");
    params.put("postal", "92688");

    var query = params.keySet().stream()
      .map(key -> key + "=" + URLEncoder.encode(params.get(key), StandardCharsets.UTF_8))
      .collect(Collectors.joining("&"));

    var host = "https://address.melissadata.net";
    var pathname = "/V3/WEB/GlobalAddress/doGlobalAddress";
    var request = HttpRequest.newBuilder()
      .GET()
      .uri(URI.create(host + pathname + '?' + query))
      .header("Accept", "application/json")
      .header("Content-Type", "application/json")
      .build();

    var response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

    System.out.println(response.body());
  }
}

