using System;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Threading.Tasks;
using System.Text;
using System.Text.Json;

public class Program
{
  public static async Task Main()
  {
    System.Net.Http.HttpClient client = new();

    string json = JsonSerializer.Serialize(new
    {
      CustomerID = "REPLACE-WITH-YOUR-LICENSE-KEY",
      Options = "USPreferredCityNames:ON,OutputGeo:ON",
      Records = new object[] {
        new {
          AddressLine1 = "22382 Avenida Empresa",
          AdministrativeArea = "CA",
          Country = "US",
          Locality = "Rancho Santa Margarita",
          Organization = "Melissa",
          PostalCode = "92688",
          RecordID = "1"
        },
        new {
          AddressLine1 = "Caecilienstr. 42-44",
          Country = "Germany",
          Locality = "Cologne",
          Organization = "Melissa",
          PostalCode = "50667",
          RecordID = "2"
        }
      },
      TransmissionReference = "Test"
    });

    using StringContent postData = new(json, Encoding.UTF8);
    postData.Headers.ContentType =
        new MediaTypeHeaderValue("application/json");

    using HttpResponseMessage request = await client.PostAsync("https://address.melissadata.net/V3/WEB/GlobalAddress/doGlobalAddress", postData);
    string response = await request.Content.ReadAsStringAsync();

    Console.WriteLine(response);
  }
}
